function exactBankKey(x){return [x.u,x.l,String(x.t).replace(/\s+/g,' ').trim(),[...x.o].map(v=>String(v).replace(/\s+/g,' ').trim()).sort().join('|')].join('§')}
function removeExactDuplicatesInPlace(items){const seen=new Set();for(let i=items.length-1;i>=0;i--){const key=exactBankKey(items[i]);if(seen.has(key))items.splice(i,1);else seen.add(key);}return items}
