function readingStem(x,seed){const lead=['請閱讀題目資料並判斷：','根據情境與附圖作答：','先整理已知條件，再選出正確結果：','請比較數量關係後計算：','閱讀任務說明，完成必要運算：','請由圖表或算式找出答案：'][Math.abs(seed)%6];return {...x,t:lead+x.t};}
